def bounded(p,cap,sha):
 s=p.lstat();assert p.is_file() and not p.is_symlink() and s.st_size<=cap;b=p.read_bytes();t=p.stat();assert (s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns)==(t.st_dev,t.st_ino,t.st_size,t.st_mtime_ns) and hashlib.sha256(b).hexdigest()==sha;return b
bounded(D/'VERIFICATION.json',16000,a['verification_sha256']);bounded(D/'child_nll_terminal_check_v1.py',100000,a['verifier_checker_sha256']);bounded(B/'data/artifacts/runs'/a['run_name']/'provenance.json',1000000,a['files']['provenance.json']['sha256'])
K=('InvocationID','LoadState','ActiveState','SubState','MainPID','Result','ExecMainCode','ExecMainStatus','ControlGroup','CPUUsageNSec','MemoryCurrent','MemoryPeak')
def show(u):
 p=subprocess.run(['systemctl','--user','show','--all',u,*sum((['-p',k] for k in K),[])],capture_output=True,text=True,timeout=15);assert p.returncode==0;return dict(x.split('=',1) for x in p.stdout.splitlines() if '=' in x)
def good(u,inv):
 s=show(u);assert s['LoadState']=='loaded' and s['Result']=='success';assert (s['InvocationID'],s['ActiveState'],s['SubState'],s['MainPID'],s['ExecMainCode'],s['ExecMainStatus'])==(inv,'active','exited','0','1','0');return s
def parent():
 s=show('wnn-campaign.slice');assert s['ControlGroup'] not in ('','/');g=Path('/sys/fs/cgroup')/s['ControlGroup'].lstrip('/');ps=[g/'cgroup.procs',*g.rglob('cgroup.procs')];assert len(ps)<128;pop={str(p):x for p in ps if p.is_file() and (x:=p.read_text().strip())};ev={n:(g/n).read_text() for n in ('memory.current','memory.events','memory.events.local') if (g/n).is_file()};return s,pop,ev
before=good(U,I);vb=good(V,VI);pb,popb,eb=parent();assert not popb
stop=subprocess.run(['systemctl','--user','stop',U,V],capture_output=True,text=True,timeout=30,check=False)
after=show(U);va=show(V);pa,popa,ea=parent()
print(json.dumps({'schema':'fg19-child-nll-exact-owned-stop.v1','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'unit':U,'invocation_id':I,'acceptance_sha256':ACCEPTANCE_SHA,'before':before,'after':after,'stop':{'returncode':stop.returncode,'stdout':stop.stdout,'stderr':stop.stderr},'verifier':{'unit':V,'invocation_id':VI,'before':vb,'after':va},'parent_before':pb,'populated_before':popb,'events_before':eb,'parent_after':pa,'populated_after':popa,'events_after':ea,'scope':'One exact stop of accepted native NLL fit plus its one successful integrity verifier only; all prior completed, failed, foreign and other units excluded. No checkpoint/model/array payload read or hash; only bounded integrity/provenance metadata/source.'},sort_keys=True))
